      "res_8k_notes": "Premium TVs. Limited content.",
      "res_dci4k_notes": "Cinema standard.",
      "ri_air": "Air (STP)",
      "ri_air_notes": "Essentially same as vacuum for most purposes.",
      "ri_crown": "Crown glass",
      "ri_crown_notes": "Standard eyeglass + lens material.",
      "ri_cz": "Cubic zirconia",
      "ri_cz_notes": "Higher than glass — used as diamond simulant.",
      "ri_diamond": "Diamond",
      "ri_diamond_notes": "Very high. Critical angle just 24.4° → \"fire\" via total internal reflection.",
      "ri_ethanol": "Ethanol",
      "ri_ethanol_notes": "Slightly more refractive than water.",
      "ri_flint": "Flint glass",
      "ri_flint_notes": "Higher dispersion than crown — used in achromatic doublets.",
      "ri_glycerin": "Glycerin",
      "ri_glycerin_notes": "Submerged glass nearly invisible in glycerin (similar n).",
      "ri_meta": "Negative-index metamaterials",
      "ri_meta_notes": "Engineered structures bend light backward. Cloaking research.",
      "ri_quartz": "Quartz",
      "ri_quartz_notes": "Common in optics. Some birefringence.",
      "ri_sapphire": "Sapphire",
      "ri_sapphire_notes": "Watch crystals, smartphone camera lenses.",
      "ri_silicon": "Silicon (visible)",
      "ri_silicon_notes": "Opaque to visible but transparent in IR. Used in IR optics.",
      "ri_vacuum": "Vacuum",
      "ri_vacuum_notes": "Reference. Light travels at c = 299,792,458 m/s.",
      "ri_water": "Water (20°C)",
      "ri_water_notes": "Bends light noticeably. Critical angle (water→air) ≈ 48.6°.",
      "ripple_bright": "Bright",
      "ripple_constructive": " = constructive · ",
      "ripple_dark": "dark",
      "ripple_destructive_hint": " = destructive · 💡 drag the red sources",
